package wirestack_m8_001_consumer

import wirestack.net.*
import wirestack as api

main(): Int64 {
    let failure = api.NetworkException(api.NetworkErrorCategory.Connect,
        api.NetworkPhase.UnixSocket, api.NetworkErrorCode.ConnectRefused,
        "consumer endpoint contract",
        remoteEndpoint: Some(api.NetworkEndpoint.Unix(
            api.UnixEndpoint.abstractName([0u8, 255u8, 1u8]))))
    match (unixPeer(failure)) {
        case Some(peer) =>
            let bytes = peer.nameBytes()
            if (bytes.size != 3 || bytes[0] != 0u8 || bytes[1] != 255u8 || bytes[2] != 1u8) {
                throw IllegalStateException("Unix error endpoint bytes changed")
            }
        case None => throw IllegalStateException("Unix error endpoint was lost")
    }
    let address = api.IpAddress(api.IpAddressFamily.Ipv4, [127u8, 0u8, 0u8, 1u8])
    let endpoint = api.SocketEndpoint(address, 8080u16)
    let context = api.OperationContext(
        deadline: Some(api.Deadline.after(5 * Duration.second)))
    let stream = TcpStream.connect(endpoint, context: context)
    try {
        let payload = api.ByteSpan("hello".toArray())
        stream.writeAll(payload, context: context)
        let expectedLocalPort = internetPort(stream.localEndpoint)
        let destination = Array<Byte>(2, repeat: 0u8)
        var truncated = false
        try {
            stream.readExact(api.MutableByteSpan(destination), context: context)
        } catch (error: api.NetworkException) {
            match (error.code) {
                case api.NetworkErrorCode.UnexpectedEof => ()
                case _ => throw IllegalStateException("expected UnexpectedEof")
            }
            if (internetPort(error.localEndpoint) != expectedLocalPort ||
                internetPort(error.remoteEndpoint) != 8080u16 || destination[0] != 120u8) {
                throw IllegalStateException("truncated read lost captured endpoint or partial data")
            }
            truncated = true
            println("TRUNCATED_READ_ENDPOINTS_PASS local=${expectedLocalPort} remote=8080 partial=78")
        }
        if (!truncated) { throw IllegalStateException("truncated peer unexpectedly filled destination") }
    } finally {
        stream.close(context: context)
    }
    0
}

func forwardOneDatagram(
    socket: DatagramSocket,
    target: api.NetworkEndpoint,
    context: api.OperationContext
): Int64 {
    let received = socket.receive(65507, context: context)
    if (received.truncated) {
        throw IllegalStateException("refusing to forward a truncated datagram")
    }
    socket.sendTo(target, api.ByteSpan(received.payload), context: context)
}

func unixPeer(error: api.NetworkException): ?api.UnixEndpoint {
    match (error.remoteEndpoint) {
        case Some(api.NetworkEndpoint.Unix(endpoint)) => Some(endpoint)
        case _ => None<api.UnixEndpoint>
    }
}

func internetPort(endpoint: ?api.NetworkEndpoint): UInt16 {
    match (endpoint) {
        case Some(api.NetworkEndpoint.Internet(value)) => value.port
        case _ => throw IllegalStateException("expected captured Internet endpoint")
    }
}
